    { question: "Which deficiency disease causes night blindness?", options: ["Vitamin A deficiency", "Vitamin C deficiency", "Iron deficiency", "Calcium deficiency"], correctIndex: 0, explanation: "A lack of vitamin A causes night blindness, in which a person is not able to see clearly at night." },
    { question: "Which deficiency disease causes weak muscles and nerves, cramps and tiredness?", options: ["Rickets", "Beriberi (Vitamin B deficiency)", "Scurvy", "Goitre"], correctIndex: 1, explanation: "A lack of vitamin B causes beriberi, in which a person has weak muscles and nerves, gets cramps and feels tired easily." },
    { question: "Which deficiency disease causes wounds to take longer to heal and gums to bleed easily?", options: ["Scurvy (Vitamin C deficiency)", "Rickets (Vitamin D deficiency)", "Osteoporosis", "Anaemia"], correctIndex: 0, explanation: "A lack of vitamin C causes scurvy, in which wounds take longer to heal and gums bleed easily." },
    { question: "Which deficiency disease causes bones to become soft and weak, and what helps our body make this vitamin?", options: ["Beriberi; exercise helps make this vitamin", "Rickets (Vitamin D deficiency); sunlight helps our body make vitamin D", "Scurvy; cold water helps make this vitamin", "Goitre; sleep helps make this vitamin"], correctIndex: 1, explanation: "A lack of vitamin D causes rickets, in which bones become soft and weak. Sunlight helps our body make vitamin D." },
    { question: "Which deficiency disease causes bones to become weak and brittle, with painful, swollen joints?", options: ["Osteoporosis (Calcium deficiency)", "Beriberi", "Scurvy", "Goitre"], correctIndex: 0, explanation: "A lack of calcium causes osteoporosis, in which bones become weak and brittle, and joints pain and swell." },
    { question: "Which deficiency disease causes the neck to swell up?", options: ["Rickets", "Goitre (Iodine deficiency)", "Scurvy", "Anaemia"], correctIndex: 1, explanation: "A lack of iodine causes goitre, in which the neck swells up." },
    { question: "Which deficiency disease makes a person feel weak, tired and not fit or active?", options: ["Anaemia (Iron deficiency)", "Rickets", "Goitre", "Beriberi"], correctIndex: 0, explanation: "A lack of iron causes anaemia, in which a person feels weak and tired and does not feel fit and active." },
    { question: "What is an allergy?", options: ["A vaccination against communicable diseases", "A reaction of the body in certain ways while eating, breathing or touching certain things, such as dust", "A type of deficiency disease", "A balanced diet plan"], correctIndex: 1, explanation: "The bodies of some people react in certain ways while eating, breathing or touching a few things — for example, some people react when exposed to dust. This condition is called an allergy." }
